<?php declare(strict_types=1); /** @var Closure(mixed): string $escape */ ?>
<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= $escape($formItem['title']) ?></title><link href="<?= $escape($basePath) ?>/assets/vendor/bootstrap/bootstrap.min.css" rel="stylesheet"><style>:root{--red:#ed1c24;--ink:#17212b}*{box-sizing:border-box}body{margin:0;padding:1rem;background:#fff;font-family:system-ui;color:var(--ink)}.embed-card{max-width:48rem;margin:auto;padding:1.5rem;border:1px solid #e2e8ec;border-radius:1rem}h1{margin-top:0}.tag{display:inline-flex;padding:.2rem .55rem;border:1px solid var(--tag);border-radius:999px;color:var(--tag);font-size:.8rem;font-weight:700}label{display:block;margin-top:1rem;font-weight:650}input,select,textarea{width:100%;margin-top:.35rem;padding:.72rem;border:1px solid #b8c2ca;border-radius:.55rem;font:inherit}button{margin-top:1rem;padding:.75rem 1rem;border:0;border-radius:.55rem;background:var(--red);color:#fff;font-weight:700}.required{color:var(--red)}.success{padding:1rem;border-radius:.6rem;background:#eaf8ef;color:#176b3a}.hp{position:absolute;left:-9999px}</style></head><body><main class="embed-card"><?php if($sent):?><div class="success"><strong>Cadastro enviado com sucesso.</strong><p>Nossa equipe entrará em contato.</p></div><?php else:?><span class="tag" style="--tag:<?= $escape($formItem['tag_color']) ?>"><?= $escape($formItem['tag_name']) ?></span><h1><?= $escape($formItem['title']) ?></h1><form method="post" action="<?= $escape($basePath) ?>/formularios/<?= $escape($formItem['slug']) ?>/enviar"><input type="hidden" name="submission_id" value="<?= $escape($submissionId) ?>"><label class="hp">Website<input name="website" tabindex="-1" autocomplete="off"></label><label>Nome completo <span class="required">*</span><input name="nome" required maxlength="160" autocomplete="name"></label><div class="row"><div class="col-md-6"><label>Telefone/WhatsApp <span class="required">*</span><input name="telefone" required data-mask="phone" inputmode="tel" maxlength="16" autocomplete="tel" placeholder="(00) 00000-0000"></label></div><div class="col-md-6"><label>E-mail <span class="required">*</span><input name="email" required type="email" maxlength="190" autocomplete="email" data-normalize="email"></label></div></div><label>Curso de interesse <span class="required">*</span><input name="curso" required maxlength="160"></label><div class="row"><div class="col-md-6"><label>Polo/Cidade <span class="required">*</span><select name="polo" required><option value="">Selecione</option><?php foreach($poles as $pole):?><option value="<?= $escape($pole['code']) ?>"><?= $escape($pole['name']) ?><?= $pole['city']!==$pole['name']?' — '.$escape($pole['city']):'' ?></option><?php endforeach;?></select></label></div><div class="col-md-6"><label>Interesse (0 a 10) <span class="required">*</span><input name="interesse" required type="number" min="0" max="10"></label></div></div><label>Observações<textarea name="observacoes" maxlength="5000" rows="3"></textarea></label><label><input style="width:auto" type="checkbox" name="consentimento" value="1" required> Autorizo o uso dos dados para atendimento e contato. <span class="required">*</span></label><button type="submit">Enviar cadastro</button></form><?php endif;?></main><script src="<?= $escape($basePath) ?>/assets/js/app.js?v=5"></script></body></html>
